document.addEventListener("DOMContentLoaded",function(){const timeFilterContainer=document.getElementById("time-filter-container");if(!timeFilterContainer)return;const severityLabels={critical:gettext("Critical"),warning:gettext("Warning"),caution:gettext("Caution"),normal:gettext("Normal")};const trendLabels={up:gettext("Increasing"),down:gettext("Decreasing"),neutral:gettext("Neutral")};const moduleMeta={payment:{label:gettext("Payment Operations"),subtitle:gettext("Payment, Reconciliation & Verification bottlenecks"),icon:"💳",barColor:"#10b981",badgeBg:"bg-emerald-100 text-emerald-800"},payments:{label:gettext("Payment Operations"),subtitle:gettext("Payment, Reconciliation & Verification bottlenecks"),icon:"💳",barColor:"#10b981",badgeBg:"bg-emerald-100 text-emerald-800"},registration:{label:gettext("Registration & Population"),subtitle:gettext("KYC, Identity documents & Geographic verification"),icon:"📝",barColor:"#3b82f6",badgeBg:"bg-blue-100 text-blue-800"},deduplication:{label:gettext("Deduplication & Adjudication"),subtitle:gettext("Biometric, Needs-Adjudication & Cross-channel duplicate issues"),icon:"🔍",barColor:"#a855f7",badgeBg:"bg-purple-100 text-purple-800"},verification:{label:gettext("Payment Verification"),subtitle:gettext("PVP execution, overdue tickets & high failure rates"),icon:"✅",barColor:"#f97316",badgeBg:"bg-orange-100 text-orange-800"},grievance:{label:gettext("Grievances & Safeguarding"),subtitle:gettext("Sensitive complaints, zero-reporting & FSP concentrations"),icon:"📣",barColor:"#ef4444",badgeBg:"bg-red-100 text-red-800"},grievances:{label:gettext("Grievances & Safeguarding"),subtitle:gettext("Sensitive complaints, zero-reporting & FSP concentrations"),icon:"📣",barColor:"#ef4444",badgeBg:"bg-red-100 text-red-800"},targeting:{label:gettext("Targeting & Eligibility"),subtitle:gettext("Vulnerability criteria & payment readiness anomalies"),icon:"🎯",barColor:"#f59e0b",badgeBg:"bg-amber-100 text-amber-800"}};let currentCategory="all";let currentProgram="all";let selectedModule=null;let ndx=crossfilter([]);const dateDimension=ndx.dimension(d=>d.date);const moduleDimension=ndx.dimension(d=>d.module);const severityDimension=ndx.dimension(d=>d.severity);const trendDimension=ndx.dimension(d=>d.trend);const countryDimension=ndx.dimension(d=>d.country_slug);const riskCodeDimension=ndx.dimension(d=>d.risk_code);const categoryDimension=ndx.dimension(d=>d.category||"");const programDimension=ndx.dimension(d=>d.program_name||"");const volumeByDayGroup=dateDimension.group(d3.timeDay).reduceSum(d=>d.issue_count);const moduleGroup=moduleDimension.group().reduceSum(d=>d.issue_count);const severityGroup=severityDimension.group().reduceSum(d=>d.issue_count);const trendGroup=trendDimension.group().reduceSum(d=>d.issue_count);const countryGroup=countryDimension.group().reduceSum(d=>d.issue_count);const riskCodeGroup=riskCodeDimension.group().reduce((p,v)=>{p.issue_count+=v.issue_count;p.risk_name=v.risk_name||p.risk_name;p.module=v.module||p.module;p.program_name=v.program_name||p.program_name;p.severity=v.severity||p.severity;p.trend=v.trend||p.trend;p.percentage=v.percentage!==null&&v.percentage!==undefined?v.percentage:p.percentage;p.unit_label=v.unit_label||p.unit_label;p.description=v.description||p.description;return p},(p,v)=>{p.issue_count-=v.issue_count;return p},()=>({issue_count:0,risk_name:"",module:"",program_name:"",severity:"",trend:"",percentage:null,unit_label:"",description:""}));const totalIssues=ndx.groupAll().reduceSum(d=>d.issue_count);const criticalIssues=ndx.groupAll().reduceSum(d=>d.severity==="critical"?d.issue_count:0);const timelineElement=document.getElementById("time-focus-chart");const timelineChart=timelineElement?echarts.init(timelineElement,"macarons"):null;window.addEventListener("resize",function(){if(timelineChart)timelineChart.resize()});function formatCount(val){return d3.format(",")(val||0)}function updateKPIs(){const totalEl=document.getElementById("total-issues");const critEl=document.getElementById("total-critical");if(totalEl)totalEl.textContent=formatCount(totalIssues.value());if(critEl)critEl.textContent=formatCount(criticalIssues.value())}function renderSeverityBadge(sev){const badges={critical:'<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-red-600 text-white shadow-xs">Critical</span>',warning:'<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-amber-500 text-white shadow-xs">Warning</span>',caution:'<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-yellow-400 text-yellow-950 shadow-xs">Caution</span>',normal:'<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-emerald-600 text-white shadow-xs">Normal</span>'};return badges[sev]||`<span class="inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold bg-gray-200 text-gray-800">${sev}</span>`}function renderTrendBadge(trend){if(trend==="up"){return'<span class="inline-flex items-center gap-0.5 text-xs font-bold text-red-600" title="'+gettext("Increasing")+'"><span class="text-sm">↗</span> '+gettext("Up")+"</span>"}if(trend==="down"){return'<span class="inline-flex items-center gap-0.5 text-xs font-bold text-emerald-600" title="'+gettext("Decreasing")+'"><span class="text-sm">↘</span> '+gettext("Down")+"</span>"}return'<span class="inline-flex items-center gap-0.5 text-xs font-semibold text-gray-400" title="'+gettext("Neutral")+'"><span class="text-sm">—</span> '+gettext("Stable")+"</span>"}function updateModuleBars(){const container=document.getElementById("module-distribution-list");const countBadge=document.getElementById("modules-monitored-count");if(!container)return;const total=totalIssues.value();const modData=moduleGroup.all().filter(d=>d.key&&d.value>0).sort((a,b)=>b.value-a.value);if(countBadge){countBadge.textContent=`${modData.length} ${gettext("modules")}`}if(modData.length===0){container.innerHTML=`<div class="text-xs text-gray-400 py-3 text-center italic">${gettext("No active module issues")}</div>`;return}container.innerHTML=modData.map(d=>{const meta=moduleMeta[d.key.toLowerCase()]||{label:d.key.charAt(0).toUpperCase()+d.key.slice(1),barColor:"#3b82f6",icon:"📁"};const pct=total>0?(d.value/total*100).toFixed(1):"0.0";const isSelected=selectedModule===d.key;const selectedClass=isSelected?"ring-2 ring-blue-500 bg-blue-50/70 shadow-xs":"hover:bg-gray-50";return`\n            <div class="p-2.5 rounded-lg cursor-pointer transition-all border border-gray-200/80 ${selectedClass} module-bar-item" data-module="${d.key}">\n                <div class="flex items-center justify-between text-xs mb-1.5">\n                    <div class="flex items-center gap-1.5 font-bold text-gray-800">\n                        <span>${meta.icon}</span>\n                        <span>${meta.label}</span>\n                    </div>\n                    <div class="text-gray-700 font-bold tabular-nums">\n                        <span>${formatCount(d.value)}</span>\n                        <span class="text-[10px] font-normal text-gray-400 ml-1">(${pct}%)</span>\n                    </div>\n                </div>\n                <div class="w-full bg-gray-100 rounded-full h-1.5 overflow-hidden">\n                    <div class="h-full rounded-full transition-all duration-300" style="width: ${pct}%; background-color: ${meta.barColor}"></div>\n                </div>\n            </div>`}).join("");container.querySelectorAll(".module-bar-item").forEach(el=>{el.addEventListener("click",function(){const mod=this.dataset.module;if(selectedModule===mod){selectedModule=null;moduleDimension.filterAll()}else{selectedModule=mod;moduleDimension.filter(mod)}updateAll()})})}function updateOperationalCards(){const container=document.getElementById("operational-modules-container");if(!container)return;const activeRisks=riskCodeGroup.all().filter(d=>d.key&&d.value.issue_count>0);if(activeRisks.length===0){container.innerHTML=`\n            <div class="bg-white rounded-xl shadow-2xs border border-gray-200 p-8 text-center">\n                <div class="text-2xl mb-2">🎉</div>\n                <h4 class="text-sm font-bold text-gray-900">${gettext("No Operational Risk Anomalies")}</h4>\n                <p class="text-xs text-gray-500 mt-1">${gettext("All operational thresholds are within normal tolerances for the selected filters.")}</p>\n            </div>`;return}const byModule={};activeRisks.forEach(item=>{const modKey=(item.value.module||"other").toLowerCase();if(!byModule[modKey])byModule[modKey]=[];byModule[modKey].push(item)});const html=Object.keys(byModule).map(modKey=>{const meta=moduleMeta[modKey]||{label:modKey.toUpperCase(),subtitle:gettext("Operational metrics and bottlenecks"),icon:"📁",barColor:"#3b82f6",badgeBg:"bg-blue-100 text-blue-800"};const items=byModule[modKey].sort((a,b)=>{const rank={critical:4,warning:3,caution:2,normal:1};return(rank[b.value.severity]||0)-(rank[a.value.severity]||0)});const moduleTotal=items.reduce((acc,cur)=>acc+cur.value.issue_count,0);const cardsHtml=items.map(item=>{const v=item.value;const sev=v.severity||"normal";const sevStyles={critical:"bg-red-50/80 border-red-500 text-red-700",warning:"bg-amber-50/80 border-amber-500 text-amber-700",caution:"bg-yellow-50/80 border-yellow-400 text-yellow-800",normal:"bg-emerald-50/80 border-emerald-500 text-emerald-700"};const styleClass=sevStyles[sev]||sevStyles.normal;let trendIcon='<span class="text-gray-400 font-black text-sm" title="'+gettext("Stable")+'">—</span>';if(v.trend==="up"){trendIcon='<span class="text-red-600 font-black text-sm" title="'+gettext("Increasing")+'">↗</span>'}else if(v.trend==="down"){trendIcon='<span class="text-emerald-600 font-black text-sm" title="'+gettext("Decreasing")+'">↘</span>'}const unit=v.unit_label||gettext("issues");const valDisplay=v.percentage!==null&&v.percentage!==undefined?`${v.percentage}% <span class="text-[11px] font-normal text-gray-500">(${formatCount(v.issue_count)})</span>`:`${formatCount(v.issue_count)} <span class="text-[11px] font-normal text-gray-500">${unit}</span>`;return`\n                <div class="rounded-xl border p-3 border-l-4 transition-all shadow-2xs ${styleClass} flex flex-col justify-between">\n                    <div class="flex items-start justify-between gap-2 mb-1.5">\n                        <h5 class="text-xs font-bold text-gray-900 leading-snug">${v.risk_name||item.key}</h5>\n                        <div class="flex items-center gap-1 shrink-0">\n                            ${trendIcon}\n                        </div>\n                    </div>\n                    <div class="text-lg font-black leading-none mb-1 tabular-nums">\n                        ${valDisplay}\n                    </div>\n                    <div class="text-[10px] text-gray-600 line-clamp-2 leading-tight">\n                        ${v.description||""}\n                    </div>\n                </div>`}).join("");return`\n            <div class="bg-white rounded-xl shadow-2xs border border-gray-200 p-3.5 transition-all">\n                <div class="flex flex-wrap items-center justify-between gap-2 pb-2.5 mb-3 border-b border-gray-100">\n                    <div class="flex items-center gap-2">\n                        <span class="text-lg">${meta.icon}</span>\n                        <div>\n                            <h4 class="text-xs font-bold uppercase tracking-wider text-gray-900 leading-tight">${meta.label}</h4>\n                            <p class="text-[10px] text-gray-500">${meta.subtitle}</p>\n                        </div>\n                    </div>\n                    <span class="text-[11px] font-bold px-2.5 py-0.5 rounded-full ${meta.badgeBg}">\n                        ${formatCount(moduleTotal)} ${gettext("Issues")}\n                    </span>\n                </div>\n                <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-2.5">\n                    ${cardsHtml}\n                </div>\n            </div>`}).join("");container.innerHTML=html}function updateTopTable(){const topRisks=riskCodeGroup.all().filter(d=>d.key&&d.value.issue_count>0).sort((a,b)=>b.value.issue_count-a.value.issue_count);const tableBody=document.getElementById("risk-top-table");if(tableBody){tableBody.innerHTML=topRisks.map(d=>{const v=d.value;const pct=v.percentage!==null&&v.percentage!==undefined?`${v.percentage}%`:"—";return`<tr class="hover:bg-slate-50/80 transition-colors">\n                    <td class="py-2.5 px-3 font-semibold text-gray-900 text-xs">${v.risk_name||d.key}</td>\n                    <td class="py-2.5 px-3 text-gray-600 text-xs">${v.module}</td>\n                    <td class="py-2.5 px-3 text-gray-600 text-xs">${v.program_name||"—"}</td>\n                    <td class="py-2.5 px-3 text-center">${renderSeverityBadge(v.severity)}</td>\n                    <td class="py-2.5 px-3 text-center">${renderTrendBadge(v.trend)}</td>\n                    <td class="py-2.5 px-3 text-right font-bold text-gray-900 text-xs tabular-nums">${formatCount(v.issue_count)}</td>\n                    <td class="py-2.5 px-3 text-right font-semibold text-gray-700 text-xs tabular-nums">${pct}</td>\n                </tr>`}).join("")}}function updateAll(){updateKPIs();updateModuleBars();updateOperationalCards();updateTopTable();if(timelineChart){const timelineData=volumeByDayGroup.all().filter(d=>d.key!==null).map(d=>[d.key.getTime(),d.value]);timelineChart.setOption({tooltip:{trigger:"axis",formatter:function(params){const date=new Date(params[0].value[0]);return`${d3.timeFormat("%B %d, %Y")(date)}<br/><b>${formatCount(params[0].value[1])}</b> ${gettext("issues")}`}},toolbox:{show:true,right:10,top:0,feature:{saveAsImage:{show:true,title:gettext("Download PNG"),name:"risk_timeline",pixelRatio:2,backgroundColor:"#ffffff"}}},grid:{top:15,bottom:25,left:45,right:15},xAxis:{type:"time",axisLabel:{color:"#64748b",fontSize:10}},yAxis:{type:"value",axisLabel:{color:"#64748b",fontSize:10},splitLine:{lineStyle:{type:"dashed",color:"#f1f5f9"}}},series:[{name:gettext("Issues"),type:"bar",data:timelineData,itemStyle:{color:"#00adef",borderRadius:[2,2,0,0]},barMaxWidth:16}]},{notMerge:true})}}async function loadRange(startDate,endDate){try{const from=timeFilter.formatDateStr(startDate);const to=timeFilter.formatDateStr(endDate);const url=`${window.DASHBOARD_CONFIG.endpoint}?date_from=${from}&date_to=${to}&dashboard=risk`;const response=await fetch(url,{credentials:"same-origin",headers:{Accept:"application/json","X-Requested-With":"XMLHttpRequest"}});if(!response.ok){if(response.status===403){console.error("Authentication required. Please log in.");return}throw new Error(`HTTP error! status: ${response.status}`)}const data=await response.json();const dateFormat=d3.timeParse("%Y-%m-%d");data.forEach(d=>{d.date=dateFormat(d.date);d.issue_count=+d.issue_count;d.percentage=d.percentage===null||d.percentage===undefined?null:+d.percentage;d.severity=d.severity||"normal";d.trend=d.trend||"neutral";d.module=d.module||"";d.program_name=d.program_name||"";d.category=d.category||"";d.risk_code=d.risk_code||d.dimension_value||"";d.description=d.description||"";d.unit_label=d.unit_label||""});dateDimension.filterAll();ndx.remove();ndx.add(data);timeFilter.setBuffer(startDate,endDate);updateExportLinks(startDate,endDate);updateAll();populateProgramFilter()}catch(error){console.error("Error loading risk data:",error)}}function updateExportLinks(startDate,endDate){const base=window.DASHBOARD_CONFIG.exportEndpoint;const from=timeFilter.formatDateStr(startDate);const to=timeFilter.formatDateStr(endDate);const params=`date_from=${from}&date_to=${to}`;const csv=document.getElementById("export-csv");const xlsx=document.getElementById("export-xlsx");const json=document.getElementById("export-json");const contextInfo=document.getElementById("export-context-info");if(csv)csv.href=`${base}?format=csv&${params}`;if(xlsx)xlsx.href=`${base}?format=xlsx&${params}`;if(json)json.href=`${base}?format=json&${params}`;if(contextInfo){contextInfo.textContent=`${gettext("Period:")} ${from} → ${to}`}}const timeFilter=new DashboardTimeFilter({onFilterChange:(startDate,endDate)=>{if(timeFilter.isWithinBuffer(startDate,endDate)){dateDimension.filterRange([startDate,endDate]);updateExportLinks(startDate,endDate);updateAll()}else{loadRange(startDate,endDate)}}});const exportModal=document.getElementById("export-modal");const openExportBtn=document.getElementById("btn-open-export");const closeExportBtn=document.getElementById("btn-close-export");const cancelExportBtn=document.getElementById("btn-cancel-export");const printReportBtn=document.getElementById("btn-print-report");if(openExportBtn&&exportModal){openExportBtn.addEventListener("click",function(){if(typeof exportModal.showModal==="function"){exportModal.showModal()}else{exportModal.classList.remove("hidden")}})}function closeModal(){if(!exportModal)return;if(typeof exportModal.close==="function"){exportModal.close()}else{exportModal.classList.add("hidden")}}if(closeExportBtn)closeExportBtn.addEventListener("click",closeModal);if(cancelExportBtn)cancelExportBtn.addEventListener("click",closeModal);if(printReportBtn){printReportBtn.addEventListener("click",function(){closeModal();setTimeout(()=>{window.print()},300)})}const exportTableCsvBtn=document.getElementById("btn-export-table-csv");if(exportTableCsvBtn){exportTableCsvBtn.addEventListener("click",function(){const topRisks=riskCodeGroup.all().filter(d=>d.key&&d.value.issue_count>0);let csv="Risk Indicator,Module,Programme,Severity,Trend,Issues,Percentage\n";topRisks.forEach(d=>{const v=d.value;const name=(v.risk_name||d.key).replace(/"/g,'""');const prog=(v.program_name||"").replace(/"/g,'""');const pct=v.percentage!==null&&v.percentage!==undefined?`${v.percentage}%`:"";csv+=`"${name}","${v.module}","${prog}","${v.severity}","${v.trend}",${v.issue_count},"${pct}"\n`});const blob=new Blob([csv],{type:"text/csv;charset=utf-8;"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download="hope_risk_indicators.csv";document.body.appendChild(a);a.click();document.body.removeChild(a);URL.revokeObjectURL(url)})}const categoryTabs=document.querySelectorAll(".risk-category-tab");categoryTabs.forEach(btn=>{btn.addEventListener("click",function(){currentCategory=this.dataset.category;categoryTabs.forEach(b=>{b.classList.remove("bg-blue-50","text-blue-800","border-blue-200","active-category");b.classList.add("bg-gray-100","text-gray-700")});this.classList.add("bg-blue-50","text-blue-800","border-blue-200","active-category");this.classList.remove("bg-gray-100","text-gray-700");if(currentCategory==="all"){categoryDimension.filterAll()}else{categoryDimension.filter(currentCategory)}updateAll()})});const programSelect=document.getElementById("program-filter");function populateProgramFilter(){if(!programSelect)return;const names=programDimension.group().all().map(d=>d.key).filter(name=>name).sort();const current=programSelect.value;programSelect.innerHTML='<option value="all">'+gettext("All programmes")+"</option>"+names.map(n=>`<option value="${n}">${n}</option>`).join("");programSelect.value=current==="all"||!names.includes(current)?"all":current}if(programSelect){programSelect.addEventListener("change",function(){currentProgram=this.value;if(currentProgram==="all"){programDimension.filterAll()}else{programDimension.filter(currentProgram)}updateAll()})}loadRange(timeFilter.currentRange.start,timeFilter.currentRange.end)});
